import { AbsoluteFill, Img, staticFile, useCurrentFrame } from 'remotion';

/** Film grain and vignette over everything (grain tiles are generated by the backend into the public dir). */
export function Finish({ grain = true, strength = 0.42 }: { grain?: boolean; strength?: number }) {
  const frame = useCurrentFrame();
  return <AbsoluteFill style={{ pointerEvents: 'none' }}>
    <AbsoluteFill style={{ background: `radial-gradient(ellipse at 50% 50%, rgba(0,0,0,0) 52%, rgba(0,0,0,${strength}) 100%)` }} />
    {grain && <Img src={staticFile(`grain/${frame % 6}.png`)} style={{ width: '100%', height: '100%', objectFit: 'cover', mixBlendMode: 'overlay', opacity: 0.22 }} />}
  </AbsoluteFill>;
}

/** SVG filters used by transitions for directional motion blur. */
export function Filters() {
  const steps = [4, 8, 16, 28, 44];
  return <svg width="0" height="0" style={{ position: 'absolute' }}>
    {steps.map(s => <filter key={`h${s}`} id={`hblur${s}`} x="-20%" y="-5%" width="140%" height="110%"><feGaussianBlur stdDeviation={`${s} 0`} /></filter>)}
    {steps.map(s => <filter key={`v${s}`} id={`vblur${s}`} x="-5%" y="-20%" width="110%" height="140%"><feGaussianBlur stdDeviation={`0 ${s}`} /></filter>)}
  </svg>;
}

/** The nearest directional blur filter for a blur amount in px (0 = none). */
export function motionBlur(amount: number, axis: 'h' | 'v' = 'h') {
  if (amount < 2) return 'none';
  const steps = [4, 8, 16, 28, 44];
  const step = steps.reduce((a, b) => (Math.abs(b - amount) < Math.abs(a - amount) ? b : a));
  return `url(#${axis}blur${step})`;
}
